package com.curso.services;
import com.curso.domains.*;import com.curso.domains.dtos.InvestimentoDTOs.TransacaoRequest;import com.curso.domains.enums.TipoTransacao;import com.curso.repositories.*;import com.curso.services.exceptions.RegraNegocioException;import com.curso.cansil.CansilApplication;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=CansilApplication.class)class TransacaoConcurrencyTest{@Autowired TransacaoService service;@Autowired UsuarioRepository usuarios;@Autowired AtivoRepository ativos;@Autowired CorretoraRepository corretoras;
 @Test void duasVendasConcorrentesNaoUltrapassamOSaldo()throws Exception{String n=Long.toString(System.nanoTime()),email="conc"+n+"@test.com";Usuario u=usuarios.save(new Usuario(null,"Concorrência",email,n.substring(n.length()-11),"h"));Ativo ativo=ativos.save(new Ativo(null,"CNC"+n.substring(n.length()-2),"Ativo concorrente","B3"));Corretora xp=corretoras.save(new Corretora(u,"19131243000197","Corretora de teste",com.curso.domains.enums.Mercado.BR,true,java.time.Instant.now()));autenticar(email);service.registrar(new TransacaoRequest(ativo.getSimbolo(),xp.getId(),TipoTransacao.COMPRA,new BigDecimal("10"),new BigDecimal("20"),LocalDateTime.of(2026,9,1,10,0)));SecurityContextHolder.clearContext();var pool=Executors.newFixedThreadPool(2);var prontos=new CountDownLatch(2);var inicio=new CountDownLatch(1);Callable<Boolean> venda=()->{autenticar(email);prontos.countDown();inicio.await(10,TimeUnit.SECONDS);try{service.registrar(new TransacaoRequest(ativo.getSimbolo(),xp.getId(),TipoTransacao.VENDA,new BigDecimal("6"),new BigDecimal("21"),LocalDateTime.of(2026,9,1,11,0)));return true;}catch(RegraNegocioException e){return false;}finally{SecurityContextHolder.clearContext();}};try{Future<Boolean>a=pool.submit(venda),b=pool.submit(venda);assertTrue(prontos.await(10,TimeUnit.SECONDS));inicio.countDown();int sucessos=(a.get(20,TimeUnit.SECONDS)?1:0)+(b.get(20,TimeUnit.SECONDS)?1:0);assertEquals(1,sucessos);autenticar(email);assertEquals(new BigDecimal("4.000000"),service.posicoes().get(0).quantidade());}finally{SecurityContextHolder.clearContext();inicio.countDown();pool.shutdownNow();}}
 private static void autenticar(String email){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,""));}
}
